/* ============================================================
   LEVEL TABLE
   ============================================================ */
const LEVELS = [0,100,250,450,700,1000,1400,1900,2500,3200,4000];
const LEVEL_NAMES = ['','中文新兵','文字學徒','語言少俠','知識達人','文學精英','修辭大師','成語宗師','閱讀王者','語文霸主','中文冒險王'];

